class Solution {
    vector<vector<pair<int,int>>> children;
    pair<long long,long long> dfs(int u) {
        long long base = 0, gain = 0;
        for (auto e : children[u]) {
            auto child = dfs(e.first);
            base += child.first;
            gain = max(gain, (long long)e.second + child.second - child.first);
        }
        return {base + gain, base};
    }
public:
    long long maxScore(vector<vector<int>>& edges) {
        int n = edges.size();
        children.assign(n, {});
        for (int i = 1; i < n; ++i)
            children[edges[i][0]].push_back({i, edges[i][1]});
        return dfs(0).first;
    }
};
